
import { ethers } from 'ethers';

// SimpleStorage contract - ABI for the simple storage contract
const SIMPLE_STORAGE_ABI = [
  "function set(uint256 x)",
  "function get() view returns (uint256)",
  "function storedData() view returns (uint256)"
];

// Counter contract ABI
const COUNTER_ABI = [
  "function count() view returns (uint256)",
  "function increment()",
  "function decrement()",
  "function getCount() view returns (uint256)"
];

// ERC20 Token contract ABI - Updated to match OpenZeppelin ERC20 implementation
const ERC20_ABI = [
  "constructor(string memory name_, string memory symbol_)",
  "function name() public view returns (string memory)",
  "function symbol() public view returns (string memory)",
  "function decimals() public view returns (uint8)",
  "function totalSupply() public view returns (uint256)",
  "function balanceOf(address account) public view returns (uint256)",
  "function transfer(address to, uint256 amount) public returns (bool)",
  "function allowance(address owner, address spender) public view returns (uint256)",
  "function approve(address spender, uint256 amount) public returns (bool)",
  "function transferFrom(address from, address to, uint256 amount) public returns (bool)",
  "event Transfer(address indexed from, address indexed to, uint256 value)",
  "event Approval(address indexed owner, address indexed spender, uint256 value)"
];

// Counter contract bytecode - compiled from the reference contract
const COUNTER_BYTECODE = "";

// SimpleStorage contract bytecode - compiled from the reference contract WITHOUT initial value
const SIMPLE_STORAGE_BYTECODE = "";

// ERC20 Token contract bytecode - compiled from OpenZeppelin ERC20 implementation
const ERC20_BYTECODE = "";

// Function to validate bytecode format
const validateBytecode = (bytecode: string): string => {
  if (!bytecode || typeof bytecode !== 'string') {
    throw new Error("Invalid bytecode: bytecode must be a string");
  }
  
  // Ensure it starts with 0x
  if (!bytecode.startsWith('0x')) {
    bytecode = '0x' + bytecode;
  }
  
  // Ensure it has a valid length (must be even)
  if (bytecode.length % 2 !== 0) {
    throw new Error("Invalid bytecode length: must be even");
  }
  
  // Simple hex validation
  if (!/^0x[0-9a-fA-F]+$/.test(bytecode)) {
    throw new Error("Invalid bytecode format: must contain only hex characters");
  }
  
  return bytecode;
};

// Convert a number to BigInt with 18 decimals (for token supply)
const toTokenAmount = (amount: string): bigint => {
  const value = parseFloat(amount);
  if (isNaN(value) || value <= 0) {
    throw new Error("Invalid token amount: must be a positive number");
  }
  
  // Convert to BigInt with 18 decimals (multiply by 10^18)
  return ethers.parseUnits(amount, 18);
};

interface TokenDetails {
  name: string;
  symbol: string;
  supply: string;
}

// Function to get contract details based on mode
export const getContractByMode = (
  mode: string,
  tokenDetails: TokenDetails = { name: "MyToken", symbol: "MTK", supply: "1000000" }
) => {
  if (mode === 'basic') {
    console.log("Getting contract for basic mode");
    
    // Use Counter contract
    const bytecode = validateBytecode(COUNTER_BYTECODE);
    return {
      abi: COUNTER_ABI,
      bytecode: bytecode,
      contractArgs: [] // Counter doesn't need constructor arguments
    };
  } else if (mode === 'storage') {
    console.log("Getting contract for SimpleStorage mode");
    
    // For SimpleStorage with NO initial value parameter (no constructor)
    const bytecode = validateBytecode(SIMPLE_STORAGE_BYTECODE);
    
    console.log("SimpleStorage without initial value");
    
    return {
      abi: SIMPLE_STORAGE_ABI,
      bytecode: bytecode,
      contractArgs: [] // No constructor arguments for SimpleStorage
    };
  } else if (mode === 'erc20') {
    console.log("Getting contract for ERC20 Token mode");
    
    // Validate token details
    if (!tokenDetails.name || tokenDetails.name.trim() === '') {
      tokenDetails.name = "MyToken";
    }
    
    if (!tokenDetails.symbol || tokenDetails.symbol.trim() === '') {
      tokenDetails.symbol = "MTK";
    }
    
    if (!tokenDetails.supply || tokenDetails.supply.trim() === '' || isNaN(parseFloat(tokenDetails.supply))) {
      tokenDetails.supply = "1000000";
    }
    
    const bytecode = validateBytecode(ERC20_BYTECODE);
    
    console.log(`ERC20 Token with name: ${tokenDetails.name}, symbol: ${tokenDetails.symbol}, and supply: ${tokenDetails.supply}`);
    
    // For the updated ERC20 implementation based on your reference (OpenZeppelin style)
    // We only need name and symbol as constructor arguments
    return {
      abi: ERC20_ABI,
      bytecode: bytecode,
      contractArgs: [tokenDetails.name, tokenDetails.symbol]
    };
  } else {
    throw new Error(`Unsupported deployment mode: ${mode}`);
  }
};
